package dev.whoop4.bloop.protocol

/*
 * Whoop 4.0 notification decoders: a Kotlin port of src/whoop4/packet.py (parse_historical_record,
 * parse_event_packet, WhoopPacket.from_data), plus the METADATA / GET_CLOCK / CONSOLE_LOGS handling in
 * src/whoop4/drain.py and src/whoop4/monitor/server.py. Behaviour is kept identical to the Python
 * reference and verified by GoldenVectorsTest against vectors generated by tools/golden.py.
 *
 * Extra fields the Python code does not expose (record sequence counter, flags, event clock) are decoded
 * from offsets documented in packet.py, and they never change what the reference fields contain.
 */

private fun ByteArray.u8(o: Int) = this[o].toInt() and 0xFF
private fun ByteArray.u16(o: Int) = u8(o) or (u8(o + 1) shl 8)
private fun ByteArray.s16(o: Int) = u16(o).toShort().toInt()
private fun ByteArray.u32(o: Int): Long = (u16(o).toLong() or (u16(o + 2).toLong() shl 16))
private fun ByteArray.f32(o: Int): Float = java.lang.Float.intBitsToFloat(u32(o).toInt())

/** Python-style slice: clamps instead of throwing. */
private fun ByteArray.slice(from: Int, to: Int): ByteArray {
    val a = from.coerceIn(0, size)
    val b = to.coerceIn(a, size)
    return copyOfRange(a, b)
}

internal fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it.toInt() and 0xFF) }

/** One framed notification: payload = [type][seq][cmd][data…]. */
class Packet(val type: Int, val seq: Int, val cmd: Int, val data: ByteArray) {
    companion object {
        /**
         * Mirrors `WhoopPacket.from_data`: requires SOF 0xAA and ≥ 8 bytes; the payload is
         * raw[4 : 4 + len - 4] (clamped, as Python slicing is); returns null if the payload is < 3 bytes.
         * CRCs are not validated (the band's outbound CRC32 uses a non-standard variant).
         */
        fun parse(raw: ByteArray): Packet? {
            if (raw.size < 8 || raw.u8(0) != Framing.SOF) return null
            val len = raw.u16(1)
            val payload = raw.slice(4, 4 + len - 4)
            if (payload.size < 3) return null
            return Packet(payload.u8(0), payload.u8(1), payload.u8(2), payload.copyOfRange(3, payload.size))
        }
    }
}

/** Accelerometer sample in g (float32 as sent by the band, not rounded). */
data class Accel(val x: Float, val y: Float, val z: Float)

/** A HISTORICAL_DATA (0x2F) record. Field rules follow `parse_historical_record`. */
data class HistoricalRecord(
    val sequence: Long,          // bytes 0-3 (not in the Python output)
    val timestamp: Long,         // Unix seconds, bytes 4-7
    val subsec: Int,             // bytes 8-9, sub-second tiebreaker
    val flags: Long?,            // bytes 10-13 (not in the Python output); null if record too short
    val hr: Int,                 // byte 14
    val rrMs: List<Int>,         // up to 4, each 200..2500 ms; empty if none
    val accel: Accel?,           // bytes 33-44, only if every axis is within (-100, 100)
)

object HistoricalParser {
    const val TS_MIN = 1577836800L   // 2020-01-01
    const val TS_MAX = 1893456000L   // 2030-01-01

    fun parse(d: ByteArray): HistoricalRecord? {
        if (d.size < 15) return null
        val timestamp = d.u32(4)
        val hr = d.u8(14)
        if (timestamp < TS_MIN || timestamp > TS_MAX) return null
        if (hr == 0 || hr > 220) return null

        val rr = ArrayList<Int>(4)
        if (d.size >= 16) {
            val n = d.u8(15)
            if (n in 1..4 && d.size >= 16 + n * 2) {
                for (i in 0 until n) {
                    val ms = d.u16(16 + i * 2)
                    if (ms in 200..2500) rr.add(ms)
                }
            }
        }
        var accel: Accel? = null
        if (d.size >= 45) {
            val x = d.f32(33); val y = d.f32(37); val z = d.f32(41)
            // NaN fails these comparisons, as in Python.
            if (listOf(x, y, z).all { it > -100f && it < 100f }) accel = Accel(x, y, z)
        }
        return HistoricalRecord(
            sequence = d.u32(0), timestamp = timestamp, subsec = d.u16(8),
            flags = if (d.size >= 14) d.u32(10) else null,
            hr = hr, rrMs = rr, accel = accel,
        )
    }
}

/** EVENT (0x30) types, from project-whoopsie/whoopsie-protocol via packet.py. */
object EventType {
    const val BATTERY_LEVEL = 3
    const val WRIST_ON = 9
    const val WRIST_OFF = 10
    const val DOUBLE_TAP = 14
    const val TEMPERATURE_LEVEL = 17
    const val SENSOR_SNAPSHOT = 29
    const val UNKNOWN_32 = 32
    const val EXTENDED_BATTERY_INFORMATION = 63
    const val STATE_MARKER_A = 101
    const val STATE_MARKER_B = 102
    const val STATE_MARKER_C = 103
}

/**
 * A decoded EVENT packet. [name] matches Python's `event` key exactly, including being null where
 * Python sets no `event` key (a TEMPERATURE_LEVEL with an implausible value).
 */
data class BandEvent(
    val eventType: Int,
    val rawHex: String,               // Python `_raw`
    val name: String?,                // Python `event`
    val batteryPct: Double? = null,   // Python `battery_pct`
    val skinTempC: Double? = null,    // Python `skin_temp_c`
    val payloadBitsHex: String? = null, // Python `payload_bits` (state markers)
    val deviceClock: Long? = null,    // header bytes 1-4 (~70 ticks/s, not Unix time); not in Python output
    val subClock: Int? = null,        // header bytes 5-6; not in Python output
    val payload: ByteArray = ByteArray(0),
)

object EventParser {
    fun parse(pkt: Packet): BandEvent? {
        if (pkt.type != PacketType.EVENT) return null
        val raw = pkt.data
        val t = pkt.cmd
        var payload = ByteArray(0)
        var clock: Long? = null
        var sub: Int? = null
        if (raw.size >= 9) {
            val plen = raw.u16(7)
            payload = if (plen != 0) raw.slice(9, 9 + plen) else ByteArray(0)
            clock = raw.u32(1); sub = raw.u16(5)
        }
        val base = BandEvent(t, raw.toHex(), null, deviceClock = clock, subClock = sub, payload = payload)
        val p = payload
        return when {
            t == EventType.WRIST_ON -> base.copy(name = "wrist_on")
            t == EventType.WRIST_OFF -> base.copy(name = "wrist_off")
            t == EventType.DOUBLE_TAP -> base.copy(name = "double_tap")
            t == EventType.BATTERY_LEVEL && p.size >= 7 -> {
                val pct = p.u32(1) / 10.0
                if (pct in 0.0..100.0) {
                    val temp = p.u16(5) / 100.0
                    base.copy(name = "battery", batteryPct = pct, skinTempC = if (temp in 20.0..45.0) temp else null)
                } else base.copy(name = "battery_unparsed")
            }
            t == EventType.TEMPERATURE_LEVEL && p.size >= 2 -> {
                val temp = p.s16(0) / 10.0
                if (temp in 20.0..45.0) base.copy(name = "temperature", skinTempC = temp) else base
            }
            t == EventType.SENSOR_SNAPSHOT && p.size >= 12 -> {
                val pct = p.u16(6) / 10.0
                base.copy(name = "sensor_snapshot", batteryPct = if (pct in 0.0..100.0) pct else null)
            }
            t == EventType.STATE_MARKER_A || t == EventType.STATE_MARKER_B || t == EventType.STATE_MARKER_C ->
                base.copy(name = "state_marker_$t", payloadBitsHex = p.toHex())
            else -> base.copy(name = "unknown_$t")
        }
    }
}

object MetadataType {
    const val HISTORY_START = 1
    const val HISTORY_END = 2
    const val HISTORY_COMPLETE = 3
}

/** METADATA (0x31). Offsets as in server.py / drain.py: start/end @4/@8, trim @10. */
data class Metadata(val kind: Int, val startOffset: Long? = null, val endOffset: Long? = null, val trim: Long? = null)

object MetadataParser {
    fun parse(pkt: Packet): Metadata? {
        if (pkt.type != PacketType.METADATA) return null
        val d = pkt.data
        return when {
            pkt.cmd == MetadataType.HISTORY_START && d.size >= 12 -> Metadata(pkt.cmd, startOffset = d.u32(4), endOffset = d.u32(8))
            pkt.cmd == MetadataType.HISTORY_END && d.size >= 14 -> Metadata(pkt.cmd, trim = d.u32(10))
            else -> Metadata(pkt.cmd)
        }
    }
}

/** GET_CLOCK response: hw RTC (Unix s) @2 needs ≥ 6 bytes; 32768 Hz sub-second ticks @6 need ≥ 8. */
data class ClockResponse(val hwRtc: Long?, val subsecTicks: Int?) {
    val isValid: Boolean get() = hwRtc != null && hwRtc > HistoricalParser.TS_MIN
}

object ClockParser {
    fun parse(pkt: Packet): ClockResponse? {
        if (pkt.type != PacketType.COMMAND_RESPONSE || pkt.cmd != CommandNumber.GET_CLOCK) return null
        val d = pkt.data
        return ClockResponse(if (d.size >= 6) d.u32(2) else null, if (d.size >= 8) d.u16(6) else null)
    }
}

object ConsoleParser {
    private val RTC_INVALID = Regex("""RTC timestamp (\d+) is invalid""")

    /** Text after the 11-byte header (whole data if shorter); ASCII with U+FFFD for bytes ≥ 0x80; trailing NULs removed. */
    fun parse(pkt: Packet): String? {
        if (pkt.type != PacketType.CONSOLE_LOGS) return null
        val d = if (pkt.data.size >= 11) pkt.data.copyOfRange(11, pkt.data.size) else pkt.data
        val s = buildString(d.size) { for (b in d) append(if (b >= 0) b.toInt().toChar() else '�') }
        return s.trimEnd('\u0000')
    }

    /** The firmware's "flash writes are failing because the RTC is invalid" message, if present. */
    fun invalidRtcValue(line: String): Long? = RTC_INVALID.find(line)?.groupValues?.get(1)?.toLongOrNull()
}

/** Standard GATT Heart Rate Measurement (0x2A37). RR values are kept in raw 1/1024 s units. */
data class HeartRateMeasurement(val hr: Int, val rrRaw1024: List<Int>) {
    val rrMs: List<Double> get() = rrRaw1024.map { it * 1000.0 / 1024.0 }

    companion object {
        /** Mirrors reader.py `parse_hr_measurement`; returns null where the reference would raise. */
        fun parse(v: ByteArray): HeartRateMeasurement? {
            if (v.isEmpty()) return null
            val flags = v.u8(0)
            var i = 1
            val hr: Int
            if (flags and 0x01 != 0) {
                if (v.size < 3) return null
                hr = v.u16(1); i += 2
            } else {
                if (v.size < 2) return null
                hr = v.u8(1); i += 1
            }
            if (flags and 0x08 != 0) i += 2
            val rr = ArrayList<Int>()
            if (flags and 0x10 != 0) while (i + 1 < v.size) { rr.add(v.u16(i)); i += 2 }
            return HeartRateMeasurement(hr, rr)
        }
    }
}

/**
 * Reassembles frames that arrive split across several notifications (small MTU).
 *
 * A notification starts a new frame only if it begins with a *valid header*: SOF 0xAA plus a CRC-8 of the
 * length field that matches byte 3 (the band's outbound header CRC-8 is the standard one; verified on real
 * captures). Otherwise it continues the frame being assembled. Checking only the SOF byte (as the web and
 * legacy apps do) drops a frame whenever a continuation chunk happens to start with 0xAA.
 */
class FrameAssembler(private val onFrame: (ByteArray) -> Unit) {
    private var buf: java.io.ByteArrayOutputStream? = null
    private var total = 0

    companion object {
        fun isFrameStart(chunk: ByteArray): Boolean =
            chunk.size >= 4 && chunk.u8(0) == Framing.SOF && Crc.crc8(byteArrayOf(chunk[1], chunk[2])) == chunk.u8(3)
    }

    fun feed(chunk: ByteArray) {
        if (chunk.isEmpty()) return
        if (isFrameStart(chunk)) {
            val t = 4 + chunk.u16(1)
            if (t > 4096) { buf = null; return }
            if (chunk.size >= t) { buf = null; onFrame(chunk.copyOf(t)); return }
            buf = java.io.ByteArrayOutputStream().also { it.write(chunk) }
            total = t
            return
        }
        val b = buf ?: return
        b.write(chunk)
        if (b.size() >= total) { buf = null; onFrame(b.toByteArray().copyOf(total)) }
    }

    fun reset() { buf = null }
}
